WITH valid AS (SELECT id, name, email, country, city, segment, signup_date, is_active, age, CASE WHEN is_active THEN 'Yes' ELSE 'No' END AS is_active_label FROM customers WHERE credit_limit < 12500 AND city IS DISTINCT FROM 'Berlin') SELECT * FROM (SELECT segment, country, city, age FROM valid) src PIVOT (AVG(age) AS amount, COUNT(1) AS n FOR city IN ('Chiang Mai' AS chiang_mai, 'Singapore' AS singapore, 'London' AS london))
